async function nettoyerBrouillon(titre, places) {
  const r = await fetch("/api-pedagogique/v1/brouillon", {method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({titre:titre,places:places})});
  return await r.json();
}

