async function preparerPuisEffacer(titre, places) {
  const r = await fetch("/api-pedagogique/v1/brouillon", {method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({titre:titre,places:places})});
  const brouillon = await r.json();
  const suppression = await fetch("/api-pedagogique/v1/brouillon", {method:"DELETE"});
  return {brouillon:brouillon,suppression:suppression.status};
}

