async function verifierDemonstration(nom) {
  const avant = await (await fetch("/api-pedagogique/v1/ateliers/1")).json();
  const r = await fetch("/api-pedagogique/v1/inscriptions", {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({atelierId:1,nom:nom})});
  const confirmation = await r.json();
  const apres = await (await fetch("/api-pedagogique/v1/ateliers/1")).json();
  return {confirmation:confirmation.id,placesAvant:avant.places,placesApres:apres.places};
}

